import{_ as p,a0 as i,w as r,s as a,ao as l,I as o,x as e,a1 as u,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧——截屏 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——截屏 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——截屏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——截屏 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/Daily Ubuntu Tips – Take Screenshots Of your Desktop","title":"每日Ubuntu小技巧——截屏","tag":"201402","desc":""},"relativePath":"201402/Daily Ubuntu Tips – Take Screenshots Of your Desktop.md","filePath":"[post].md"}'),d={name:"201402/Daily Ubuntu Tips – Take Screenshots Of your Desktop.md"};function b(T,t,f,m,k,g){const n=i("Link");return r(),a("div",null,[t[11]||(t[11]=l('<h1 id="每日ubuntu小技巧——截屏" tabindex="-1">每日Ubuntu小技巧——截屏 <a class="header-anchor" href="#每日ubuntu小技巧——截屏" aria-label="Permalink to “每日Ubuntu小技巧——截屏”">​</a></h1><p>Ubuntu 是一个功能强大的现代化操作系统，支持你进行多种任务。从使用 Libreoffice 创建和编辑文档到使用 GIMP 处理图片，Ubuntu 都是最佳选择。</p><p>如果你需要一个功能强大的操作系统来完成工作，那么你一定会考虑选择 Ubuntu。</p><p>你可以用 Ubuntu 来完成的另一件事情是为你的桌面截屏或者激活应用程序的窗口。你可以安装很多第三方工具来完成这些事情，但是实际没有必要，因为 Ubuntu 安装时已自带这些功能。</p><p>如果你想向别人展示如何在Ubuntu上面做一些事情，那么这个应用程序就非常有用。截屏得到的图片文件可以保存，也可以通过email发送给其他人。</p><p>使用截屏程序，需要进入到面板界面或者直接按下键盘上面的 Windows 键进入面板，Windows 键指的是键盘空格键的左边有 Windows 图标的键。</p><p>当面板打开后，找到“截屏”，然后打开这个程序(译者注：需要在已安装程序中查找或者直接在搜索框中输入“截图”)。</p><p>以下是你能够通过这个截屏程序做的操作：</p><ul><li>截取整个屏幕</li><li>截取当前程序窗口</li><li>截取特定区域</li></ul><p>如果你想在截图时将鼠标箭头一起截取，可以将在下方图片 Effects 选项中的&quot;Include pointer&quot;选项选中即可。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/screenshot.png" alt=""></p><p>当你选择好你的截屏方式后，点击图片中的‘<strong>截图</strong>’按钮，然后程序就会退出并且自动保存图片。</p><p>如果你想截取特定区域，需要选择该方式，当你点击‘<strong>截图</strong>’按钮时，鼠标会变成十字形状。此刻，你可以拖拽这个十字形状的鼠标，来得到任意你想截取的区域。在你停止拖拽鼠标后，图片会自动截取。</p><p>以上就是你在使用 Ubuntu 时，如何完成一个截图的操作。</p><p>希望能够帮助到你，欢迎再来。</p><p>享受截屏的欢乐！</p><hr>',17)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),u(n,{href:"http://www.liberiangeek.net/2013/12/daily-ubuntu-tips-take-screenshots-of-your-desktop/"},{default:s(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/12/daily-ubuntu-tips-take-screenshots-of-your-desktop/",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=e("译者：",-1)),u(n,{href:"https://github.com/liuaiping"},{default:s(()=>[...t[2]||(t[2]=[e("liuaiping",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),u(n,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),u(n,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const _=p(d,[["render",b]]);export{w as __pageData,_ as default};
